<div class="d-flex justify-content-between align-items-center mb-3"><div><h1 class="h3 mb-1">Cheque Register</h1><p class="text-secondary mb-0">Pending, cleared and bounced cheques.</p></div></div>
<div class="card shadow-sm"><div class="card-body"><div class="table-responsive"><table class="table table-sm" id="t"><thead><tr><th>No</th><th>Direction</th><th>Party</th><th>Bank</th><th>Cheque Date</th><th>Amount</th><th>Status</th><th></th></tr></thead><tbody></tbody></table></div></div></div>
<script>
$(function(){const b=<?=json_encode(url('/'),JSON_THROW_ON_ERROR)?>;function load(){$.getJSON(b+'cheques/data').done(r=>{let x=$('#t tbody').empty();(r.data.rows||[]).forEach(v=>{let a='';if(v.status==='PENDING')a='<button class="btn btn-sm btn-outline-success clear" data-id="'+v.id+'">Clear</button> <button class="btn btn-sm btn-outline-danger bounce" data-id="'+v.id+'">Bounce</button>';x.append('<tr><td>'+v.cheque_no+'</td><td>'+v.direction+'</td><td>'+v.party_code+' - '+v.party_name+'</td><td>'+(v.bank||'')+'</td><td>'+v.cheque_date+'</td><td>'+Number(v.amount).toFixed(2)+'</td><td>'+v.status+'</td><td>'+a+'</td></tr>')})})}
$(document).on('click','.clear',function(){let id=$(this).data('id');$.post(b+'cheques/'+id+'/clear',{cleared_date:new Date().toISOString().slice(0,10)}).done(r=>{alert(r.message);load()}).fail(x=>alert(x.responseJSON?.message||'Clear failed'))});$(document).on('click','.bounce',function(){let reason=prompt('Bounce reason:');if(!reason)return;$.post(b+'cheques/'+$(this).data('id')+'/bounce',{reason}).done(r=>{alert(r.message);load()}).fail(x=>alert(x.responseJSON?.message||'Bounce failed'))});load()});
</script>